    # Find separator value and positions
    sep_rows, sep_cols = [], []
    for r in range(rows):
        if len(set(grid[r])) == 1:
            sep_rows.append(r)
    for c in range(cols):
        if len(set(grid[r][c] for r in range(rows))) == 1:
            sep_cols.append(c)

    # Get block boundaries
    row_bounds = [-1] + sep_rows + [rows]
    col_bounds = [-1] + sep_cols + [cols]

    block_grid = []
    for i in range(len(row_bounds)-1):
        row = []
